package thaumcraft.test;
import java.util.*;
import com.mojang.authlib.GameProfile;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.ChestBlockEntity;
import net.minecraft.world.phys.*;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.eventbus.api.listener.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;
import thaumcraft.aura.*;
import thaumcraft.thaumaturgy.*;
import thaumcraft.research.*;
@Mod.EventBusSubscriber(modid="thaumcraft")
public final class ExchangeProbe {
 public static final BlockPos P=new BlockPos(8,180,8),Q=P.above(),SAVE=P.offset(8,0,0);
 static BlockPos deniedBreak,deniedPlace;static int breakEvents,placeEvents,ticks;static boolean done,drainDuringPlace,removeDuringPlace,reenterDuringPlace;
 public static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
 static String mode(){return System.getProperty("thaumcraft.exchangeProbe","");}
 public static ServerPlayer player(ServerLevel l,String name){var p=new ServerPlayer(l.getServer(),l,new GameProfile(UUID.nameUUIDFromBytes(name.getBytes(java.nio.charset.StandardCharsets.UTF_8)),name),ClientInformation.createDefault());new net.minecraft.server.network.ServerGamePacketListenerImpl(l.getServer(),new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND),p,net.minecraft.server.network.CommonListenerCookie.createInitial(p.getGameProfile(),false)){@Override public void send(net.minecraft.network.protocol.Packet<?> packet){}@Override public void send(net.minecraft.network.protocol.Packet<?> packet,io.netty.channel.ChannelFutureListener listener){}};p.gameMode.changeGameModeForPlayer(GameType.SURVIVAL);p.setPos(P.getX()+.5,P.getY(),P.getZ()-2.5);knowledge(p);return p;}
 public static void knowledge(ServerPlayer p){KnowledgeStore.write(p,CheatResearch.complete(KnowledgeState.EMPTY).knowledge());}
 public static ItemStack equip(ServerPlayer p,FocusProgram program){var caster=new ItemStack(thaumcraft.content.SimpleContent.ITEMS.get("caster_basic").get());var focus=new ItemStack(thaumcraft.content.SimpleContent.ITEMS.get("focus_3").get());focus.set(ThaumaturgyContent.PROGRAM.get(),program);caster.set(ThaumaturgyContent.FOCUS.get(),focus);caster.set(DataComponents.CUSTOM_NAME,Component.literal("Exchange persistence proof"));p.setItemInHand(InteractionHand.MAIN_HAND,caster);return caster;}
 static FocusProgram.Effect effect(int fortune,boolean silk){return new FocusProgram.Effect("exchange",1,1,8,fortune,silk);}
 static boolean swap(ServerPlayer p,BlockPos q,FocusProgram.Effect e){return FocusExchange.exchange(p,new BlockHitResult(Vec3.atCenterOf(q),Direction.UP,q,false),e);}
 static void source(ServerLevel l,BlockPos q,Block block){l.setBlockAndUpdate(q,block.defaultBlockState());}
 static void sample(ItemStack caster,Item item){caster.set(ThaumaturgyContent.PICKED_BLOCK.get(),new ItemStack(item));}
 static float vis(ServerLevel l,BlockPos q){return AuraManager.get(l,q).vis();}
 static void refill(ServerLevel l,BlockPos q){AuraManager.addVis(l,q,1000);}
 static int count(ServerPlayer p,Item item){int n=0;for(int i=0;i<p.getInventory().getContainerSize();i++)if(p.getInventory().getItem(i).is(item))n+=p.getInventory().getItem(i).getCount();return n;}
 static List<ItemStack> inventory(ServerPlayer p){var a=new ArrayList<ItemStack>();for(int i=0;i<p.getInventory().getContainerSize();i++)a.add(p.getInventory().getItem(i).copy());return a;}
 static void sameInventory(ServerPlayer p,List<ItemStack> before){for(int i=0;i<before.size();i++)check(ItemStack.matches(before.get(i),p.getInventory().getItem(i)),"Inventory changed at "+i);}
 @SubscribeEvent public static void breakEvent(net.minecraftforge.event.level.BlockEvent.BreakEvent e){if(mode().isEmpty())return;if(e.getPos().equals(deniedBreak)){breakEvents++;e.setResult(net.minecraftforge.common.util.Result.DENY);}}
 @SubscribeEvent public static boolean placeEvent(net.minecraftforge.event.level.BlockEvent.EntityPlaceEvent e){if(mode().isEmpty())return false;if(e.getPos().equals(deniedPlace)){placeEvents++;check(e.getPlacedBlock().is(Blocks.DIRT),"Placement hook saw wrong intended block");return true;}if(e.getEntity() instanceof ServerPlayer p){if(drainDuringPlace){drainDuringPlace=false;AuraManager.drainVis(p.level(),e.getPos(),32766,false);}if(removeDuringPlace){removeDuringPlace=false;p.getInventory().getItem(10).setCount(0);}if(reenterDuringPlace){reenterDuringPlace=false;check(!swap(p,e.getPos().east(),effect(0,false)),"Reentrant exchange was accepted");}}return false;}
 static void write(ServerLevel l){var p=player(l,"Exchange75");l.getChunkAt(P);l.getChunkAt(SAVE);refill(l,Q);var base=new FocusProgram("bolt",List.of(effect(0,false)));var caster=equip(p,base);p.setShiftKeyDown(true);source(l,Q,Blocks.DIRT);float before=vis(l,Q);var inventory=inventory(p);
  check(p.gameMode.useItemOn(p,l,caster,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(Q),Direction.NORTH,Q,false)).consumesAction(),"Native sneak use did not sample");check(ExchangeSelection.selected(caster).is(Items.DIRT)&&vis(l,Q)==before&&l.getBlockState(Q).is(Blocks.DIRT),"Sampling charged aura or changed block");check(count(p,Items.DIRT)==0,"Sampling created material");p.setShiftKeyDown(false);p.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(Items.STICK,17));p.getInventory().setItem(10,new ItemStack(Items.DIRT,3));source(l,Q,Blocks.STONE);before=vis(l,Q);check(swap(p,Q,effect(0,false)),"Selected inventory material failed");check(l.getBlockState(Q).is(Blocks.DIRT)&&count(p,Items.DIRT)==2&&count(p,Items.COBBLESTONE)==1&&p.getOffhandItem().getCount()==17&&p.getMainHandItem()==caster,"Exchange inventory/loot/equipment wrong");check(Math.abs(vis(l,Q)-(before-.25F))<.001,"Local cost wrong");
  inventory=inventory(p);before=vis(l,Q);check(!swap(p,Q,effect(0,false)),"Identical block accepted");sameInventory(p,inventory);check(vis(l,Q)==before,"Identical block charged");
  source(l,Q,Blocks.STONE);inventory=inventory(p);before=vis(l,Q);deniedPlace=Q;check(!swap(p,Q,effect(0,false)),"Placement denial ignored");deniedPlace=null;check(placeEvents==1&&l.getBlockState(Q).is(Blocks.STONE)&&vis(l,Q)==before,"Placement denial lost original or vis");sameInventory(p,inventory);
  deniedBreak=Q;check(!swap(p,Q,effect(0,false)),"Break denial ignored");deniedBreak=null;check(breakEvents==1&&l.getBlockState(Q).is(Blocks.STONE)&&vis(l,Q)==before,"Break denial changed source/vis");sameInventory(p,inventory);thaumcraft.Thaumcraft.LOGGER.info("EXCHANGE75_TRANSACTION_OK: native sample, inventory payment, pickup, exact aura, identical block and both Forge denials without holes or consumption");
  source(l,Q,Blocks.OBSIDIAN);check(swap(p,Q,effect(0,false))&&count(p,Items.OBSIDIAN)==1,"Old hardness cutoff remains");
  p.getInventory().setItem(10,new ItemStack(Items.DIRT,64));source(l,Q,Blocks.DIAMOND_ORE);before=vis(l,Q);check(swap(p,Q,effect(4,true)),"Silk exchange failed");check(count(p,Items.DIAMOND_ORE)==1&&count(p,Items.DIAMOND)==0&&Math.abs(vis(l,Q)-(before-.9F))<.001,"Silk precedence/cost wrong");
  for(int i=0;i<32;i++){source(l,Q,Blocks.DIAMOND_ORE);check(swap(p,Q,effect(4,false)),"Fortune exchange failed");}check(count(p,Items.DIAMOND)>32,"Fortune IV missing");
  source(l,Q,Blocks.CHEST);var chest=(ChestBlockEntity)l.getBlockEntity(Q);chest.setItem(0,new ItemStack(Items.DIAMOND,7));inventory=inventory(p);deniedBreak=Q;check(!swap(p,Q,effect(0,false))&&chest.getItem(0).getCount()==7,"Protected container changed");deniedBreak=null;sameInventory(p,inventory);source(l,Q,Blocks.BEDROCK);check(!swap(p,Q,effect(0,false)),"Bedrock exchanged");
  source(l,Q,Blocks.STONE);drainDuringPlace=true;inventory=inventory(p);check(!swap(p,Q,effect(0,false))&&l.getBlockState(Q).is(Blocks.STONE),"Aura exhaustion left hole");sameInventory(p,inventory);refill(l,Q);removeDuringPlace=true;check(!swap(p,Q,effect(0,false))&&l.getBlockState(Q).is(Blocks.STONE),"Material exhaustion left hole");p.getInventory().setItem(10,new ItemStack(Items.DIRT,3));reenterDuringPlace=true;check(swap(p,Q,effect(0,false)),"Outer exchange failed");
  var unloaded=new BlockPos(160008,180,8);check(!swap(p,unloaded,effect(0,false))&&l.getChunkSource().getChunkNow(10000,0)==null,"Exchange loads terrain");
  source(l,Q,Blocks.STONE);sample(caster,Items.SAND);p.getInventory().setItem(10,new ItemStack(Items.SAND,2));source(l,Q.below(),Blocks.AIR); // sand falls after commit, but placement itself is a legal single block
  sample(caster,Items.TORCH);p.getInventory().setItem(10,new ItemStack(Items.TORCH,2));source(l,Q.below(),Blocks.AIR);source(l,Q.north(),Blocks.AIR);source(l,Q.south(),Blocks.AIR);source(l,Q.east(),Blocks.AIR);source(l,Q.west(),Blocks.AIR);inventory=inventory(p);before=vis(l,Q);check(!swap(p,Q,effect(0,false))&&l.getBlockState(Q).is(Blocks.STONE)&&vis(l,Q)==before,"Unsupported placement destroyed source");sameInventory(p,inventory);
  sample(caster,Items.OAK_DOOR);p.getInventory().setItem(10,new ItemStack(Items.OAK_DOOR,2));check(!swap(p,Q,effect(0,false)),"Half multiblock placed");
  caster.remove(ThaumaturgyContent.PICKED_BLOCK.get());p.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(Items.DIRT,2));check(swap(p,Q,effect(0,false))&&p.getOffhandItem().getCount()==1,"Legacy offhand fallback failed");
  p.setGameMode(GameType.CREATIVE);sample(caster,Items.GOLD_BLOCK);source(l,Q,Blocks.STONE);inventory=inventory(p);before=vis(l,Q);check(swap(p,Q,effect(0,false))&&l.getBlockState(Q).is(Blocks.GOLD_BLOCK)&&vis(l,Q)==before,"Creative exchange charged materials/aura");sameInventory(p,inventory);p.setGameMode(GameType.SURVIVAL);
  thaumcraft.Thaumcraft.LOGGER.info("EXCHANGE75_LOOT_OK: obsidian, silk/fortune, inventories, aura/material exhaustion, unsupported/multiblock rejection, legacy fallback and creative semantics");
  p.getInventory().clearContent();var plan=new FocusProgram("plan",List.of(effect(0,false)),"none",2,10,1,5,false,List.of(),new FocusProgram.PlanSettings(1,0,0,false));caster=equip(p,plan);sample(caster,Items.DIRT);p.getInventory().setItem(10,new ItemStack(Items.DIRT,2));for(int x=-1;x<=1;x++)source(l,Q.offset(x,0,0),Blocks.STONE);p.setPos(P.getX()+.5,P.getY(),P.getZ()-3.5);p.setYRot(0);p.setXRot(0);before=vis(l,Q);check(p.gameMode.useItem(p,l,caster,InteractionHand.MAIN_HAND).consumesAction(),"Native Plan launch failed");int changed=0;for(int x=-1;x<=1;x++)if(l.getBlockState(Q.offset(x,0,0)).is(Blocks.DIRT))changed++;check(changed==2&&count(p,Items.DIRT)==0&&count(p,Items.COBBLESTONE)==2,"Plan did not stop exactly at available materials");check(Math.abs(vis(l,Q)-(before-plan.vis()-.5F))<.001,"Plan local and cast costs not exact");
  l.setBlockAndUpdate(SAVE,Blocks.CHEST.defaultBlockState());((ChestBlockEntity)l.getBlockEntity(SAVE)).setItem(0,caster.copy());thaumcraft.Thaumcraft.LOGGER.info("EXCHANGE75_WRITE_OK: native Plan pays once per successful target, saved selected sample and exact focus in real chest");
 }
 @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){if(done||!List.of("write","read").contains(mode())||++ticks<40)return;var l=e.server().overworld();l.setChunkForced(0,0,true);l.getChunkAt(SAVE);if(mode().equals("write"))write(l);else{var chest=(ChestBlockEntity)l.getBlockEntity(SAVE);check(chest!=null,"Saved chest missing");var caster=chest.getItem(0);check(caster.getItem() instanceof CasterItem&&ExchangeSelection.selected(caster).is(Items.DIRT)&&ExchangeSelection.program(caster).medium().equals("plan")&&caster.getHoverName().getString().equals("Exchange persistence proof"),"Sample/focus/name did not persist");var p=player(l,"Exchange75Read");p.setItemInHand(InteractionHand.MAIN_HAND,caster.copy());p.getInventory().setItem(10,new ItemStack(Items.DIRT,2));refill(l,Q);source(l,Q,Blocks.STONE);check(swap(p,Q,effect(0,false))&&l.getBlockState(Q).is(Blocks.DIRT)&&count(p,Items.COBBLESTONE)==1,"Restored sample not usable");thaumcraft.Thaumcraft.LOGGER.info("EXCHANGE75_RESTART_OK: selected block, nested focus and custom name survive cold restart and real exchange");}done=true;e.server().halt(false);}
}
